cssCode:
.nav-link {
  position: relative; text-decoration: none; color: #ffffff; 
  font-weight: bold; font-size: 30px; font-family: sans-serif; 
  padding-bottom: 5px; cursor: pointer;
}
.nav-link::after {
  content: ''; position: absolute; left: 0; bottom: 0; 
  width: 0; height: 4px; background: #ff007f; 
  box-shadow: 0 0 15px #ff007f; transition: width 0.4s ease;
}
.nav-link:hover::after { width: 100%; }

